'use client'

import { ScrollArea } from '@/components/ui/scroll-area'
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog'
import {
  Sheet,
  SheetContent,
  SheetDescription,
  SheetFooter,
  SheetHeader,
  SheetTitle,
} from '@/components/ui/sheet'
import { cn } from '@/lib/utils'
import { useIsMobile } from '@/hooks/useIsMobile'

const dialogWidthMap: Record<NonNullable<ResponsiveDialogProps['dialogWidth']>, string> = {
  sm: 'max-w-[448px]',
  md: 'max-w-[560px]',
  lg: 'max-w-[720px]',
}

interface ResponsiveDialogProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  title: string
  description?: string
  children: React.ReactNode
  /** Footer content (action buttons). Rendered in DialogFooter or SheetFooter. */
  footer?: React.ReactNode
  /** Max width for Dialog variant. Default: 'sm' (448px). */
  dialogWidth?: 'sm' | 'md' | 'lg'
  /** Tailwind height class for Sheet variant. Default: 'h-auto max-h-[80vh]'. */
  sheetHeight?: string
}

/**
 * Renders a Dialog on desktop (>= 768px) and a Sheet side="bottom" on mobile.
 * Single API — callers don't need to think about breakpoints.
 *
 * Usage:
 *   <ResponsiveDialog open={open} onOpenChange={setOpen} title="Confirm action"
 *     footer={<><Button onClick={…}>Cancel</Button><Button>Confirm</Button></>}>
 *     <p>Content here</p>
 *   </ResponsiveDialog>
 */
export function ResponsiveDialog({
  open,
  onOpenChange,
  title,
  description,
  children,
  footer,
  dialogWidth = 'sm',
  sheetHeight,
}: ResponsiveDialogProps) {
  const isMobile = useIsMobile()

  if (isMobile) {
    return (
      <Sheet open={open} onOpenChange={onOpenChange}>
        <SheetContent
          side="bottom"
          className={cn(
            'rounded-t-2xl p-0 flex flex-col safe-bottom',
            sheetHeight ?? 'h-auto max-h-[80vh]',
          )}
          showCloseButton={false}
        >
          {/* Drag handle */}
          <div className="flex justify-center pt-3 shrink-0" aria-hidden="true">
            <div className="h-1 w-10 rounded-full bg-border/60" />
          </div>
          <SheetHeader className="px-4 pt-2 pb-0 text-left">
            <SheetTitle>{title}</SheetTitle>
            {description && <SheetDescription>{description}</SheetDescription>}
          </SheetHeader>
          <ScrollArea className="flex-1 px-4 py-4">
            {children}
          </ScrollArea>
          {footer && (
            <SheetFooter className="px-4 pb-4 pt-0 flex-row gap-2">
              {footer}
            </SheetFooter>
          )}
        </SheetContent>
      </Sheet>
    )
  }

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className={dialogWidthMap[dialogWidth]}>
        <DialogHeader>
          <DialogTitle>{title}</DialogTitle>
          {description && <DialogDescription>{description}</DialogDescription>}
        </DialogHeader>
        <div className="py-2">{children}</div>
        {footer && <DialogFooter>{footer}</DialogFooter>}
      </DialogContent>
    </Dialog>
  )
}

