'use client'

import { useRef, useState } from 'react'
import { ArrowDown, Loader2 } from 'lucide-react'
import { cn } from '@/lib/utils'

interface PullToRefreshProps {
  onRefresh: () => Promise<void>
  children: React.ReactNode
  /** Pull threshold in px. Default: 80. */
  threshold?: number
  /** Disable on desktop — only activates on touch devices. Default: true. */
  disableOnDesktop?: boolean
  className?: string
}

function isTouchDevice(): boolean {
  return 'ontouchstart' in window || navigator.maxTouchPoints > 0
}

/**
 * Wrap a scrollable page section to enable pull-to-refresh.
 * Uses native PointerEvents — no external library needed.
 * Only activates when the container is scrolled to the top.
 *
 * Usage:
 *   <PullToRefresh onRefresh={async () => { router.refresh() }}>
 *     <DataTable ... />
 *   </PullToRefresh>
 */
export function PullToRefresh({
  onRefresh,
  children,
  threshold = 80,
  disableOnDesktop = true,
  className,
}: PullToRefreshProps) {
  const containerRef = useRef<HTMLDivElement>(null)
  const startYRef = useRef(0)
  const isDragging = useRef(false)
  const [pullDistance, setPullDistance] = useState(0)
  const [isRefreshing, setIsRefreshing] = useState(false)

  const pullProgress = Math.min(pullDistance / threshold, 1)

  const indicatorLabel =
    isRefreshing
      ? 'Refreshing\u2026'
      : pullProgress >= 1
        ? 'Release to refresh'
        : 'Pull to refresh'

  function onPointerDown(e: React.PointerEvent) {
    if (isRefreshing) return
    if (containerRef.current && containerRef.current.scrollTop > 0) return
    if (disableOnDesktop && !isTouchDevice()) return
    isDragging.current = true
    startYRef.current = e.clientY
    containerRef.current?.setPointerCapture(e.pointerId)
  }

  function onPointerMove(e: React.PointerEvent) {
    if (!isDragging.current || isRefreshing) return
    const delta = e.clientY - startYRef.current
    if (delta <= 0) return
    // Rubber-band resistance factor 0.5; cap at 1.5× threshold
    setPullDistance(Math.min(delta * 0.5, threshold * 1.5))
  }

  function onPointerUp() {
    if (!isDragging.current) return
    isDragging.current = false
    if (pullDistance >= threshold) {
      setIsRefreshing(true)
      setPullDistance(threshold) // hold at threshold while refreshing
      void Promise.resolve(onRefresh()).finally(() => {
        setIsRefreshing(false)
        setPullDistance(0)
      })
    } else {
      setPullDistance(0)
    }
  }

  return (
    <div
      ref={containerRef}
      className={cn('pull-to-refresh-container relative overflow-y-auto', className)}
      onPointerDown={onPointerDown}
      onPointerMove={onPointerMove}
      onPointerUp={onPointerUp}
      onPointerCancel={onPointerUp}
      style={{
        transform:
          isRefreshing || pullDistance > 0
            ? `translateY(${Math.min(pullDistance, threshold)}px)`
            : undefined,
        transition: !isDragging.current ? 'transform 200ms ease-out' : undefined,
      }}
    >
      {/* Indicator — visible when pulling or refreshing */}
      {(pullDistance > 0 || isRefreshing) && (
        <div
          aria-live="polite"
          aria-label={indicatorLabel}
          className={cn(
            'absolute left-0 right-0 top-0 flex items-center justify-center gap-2',
            'text-[12px] text-muted-foreground pointer-events-none select-none',
            'transition-opacity duration-200',
          )}
          style={{
            transform: `translateY(${indicatorLabel === 'Refreshing\u2026' ? -threshold : -pullDistance}px)`,
            opacity: pullProgress,
          }}
        >
          {isRefreshing ? (
            <Loader2 className="size-4 animate-spin" aria-hidden="true" />
          ) : (
            <ArrowDown
              className={cn(
                'size-4 transition-transform duration-200',
                pullProgress >= 1 && 'rotate-180',
              )}
              aria-hidden="true"
            />
          )}
          <span>{indicatorLabel}</span>
        </div>
      )}

      {children}
    </div>
  )
}

