'use client'

import { useRef, useEffect, useState } from 'react'
import { cn } from '@/lib/utils'

interface ScrollableTabsProps {
  children: React.ReactNode
  className?: string
  /**
   * Show a right-side fade gradient when tabs overflow.
   * Default: true.
   */
  showFade?: boolean
}

/**
 * B9 — Horizontally scrollable tab nav with fade-edge indicator.
 * Wraps any tab nav that might overflow on mobile.
 *
 * Usage:
 *   <ScrollableTabs>
 *     <TabsList>...</TabsList>
 *   </ScrollableTabs>
 */
export function ScrollableTabs({
  children,
  className,
  showFade = true,
}: ScrollableTabsProps) {
  const scrollRef = useRef<HTMLDivElement>(null)
  const [canScrollRight, setCanScrollRight] = useState(false)
  const [canScrollLeft, setCanScrollLeft] = useState(false)

  function updateFade() {
    const el = scrollRef.current
    if (!el) return
    setCanScrollLeft(el.scrollLeft > 4)
    setCanScrollRight(el.scrollLeft + el.clientWidth < el.scrollWidth - 4)
  }

  useEffect(() => {
    updateFade()
    const el = scrollRef.current
    if (!el) return
    el.addEventListener('scroll', updateFade, { passive: true })
    const ro = new ResizeObserver(updateFade)
    ro.observe(el)
    return () => {
      el.removeEventListener('scroll', updateFade)
      ro.disconnect()
    }
  }, [])

  return (
    <div className={cn('relative', className)}>
      {/* Left fade — appears when scrolled right */}
      {showFade && canScrollLeft && (
        <div
          aria-hidden="true"
          className="pointer-events-none absolute left-0 top-0 z-10 h-full w-8 bg-gradient-to-r from-background to-transparent"
        />
      )}

      {/* Scrollable container */}
      <div
        ref={scrollRef}
        className="overflow-x-auto scrollbar-none"
      >
        {children}
      </div>

      {/* Right fade — appears when more tabs are hidden to the right */}
      {showFade && canScrollRight && (
