'use client'

import Link from 'next/link'
import { usePathname } from 'next/navigation'
import { LayoutDashboard, CalendarDays, Users, Plus, Settings } from 'lucide-react'
import { cn } from '@/lib/utils'

/**
 * B12 — 5-slot bottom navigation bar for mobile.
 * Only visible on mobile (hidden md:hidden counterpart is the sidebar).
 * Slot 3 (center) is the primary action "New" button that opens the
 * AppointmentCreateDrawer. Uses a callback prop so the parent shell
 * can manage the drawer state.
 */

interface BottomNavProps {
  onNewAppointment: () => void
}

interface NavSlot {
  icon: React.ComponentType<{ className?: string }>
  label: string
  href: string
}

const LEFT_SLOTS: NavSlot[] = [
  { icon: LayoutDashboard, label: 'Dashboard', href: '/dashboard' },
  { icon: CalendarDays,    label: 'Schedule',  href: '/appointments' },
]

const RIGHT_SLOTS: NavSlot[] = [
  { icon: Users,    label: 'Clients',  href: '/clients' },
  { icon: Settings, label: 'Settings', href: '/settings' },
]

export function BottomNav({ onNewAppointment }: BottomNavProps) {
  const pathname = usePathname()

  function isActive(href: string) {
    if (href === '/dashboard') return pathname === '/dashboard'
    return pathname.startsWith(href)
  }

  return (
    <nav
      aria-label="Primary navigation"
      className={cn(
        // Only show on mobile
        'flex md:hidden',
        'fixed bottom-0 left-0 right-0 z-40',
        'h-16 pb-safe',
        'bg-background/95 backdrop-blur-md',
        'border-t border-border/60',
        'shadow-[0_-1px_0_0_hsl(var(--border)/0.5)]',
      )}
    >
      {/* Left 2 slots */}
      {LEFT_SLOTS.map((slot) => (
        <NavLink key={slot.href} slot={slot} active={isActive(slot.href)} />
      ))}

      {/* Center FAB — New appointment */}
      <div className="flex flex-1 items-center justify-center">
        <button
          type="button"
          onClick={onNewAppointment}
          aria-label="New appointment"
          className={cn(
            'flex flex-col items-center justify-center',
            'h-12 w-12 rounded-full',
            'bg-primary text-primary-foreground',
            'shadow-[var(--shadow-card)]',
            'transition-transform active:scale-95',
            'touch-target',
          )}
        >
          <Plus className="h-5 w-5" aria-hidden="true" />
        </button>
      </div>

      {/* Right 2 slots */}
      {RIGHT_SLOTS.map((slot) => (
        <NavLink key={slot.href} slot={slot} active={isActive(slot.href)} />
      ))}
    </nav>
  )
}

function NavLink({ slot, active }: { slot: NavSlot; active: boolean }) {
  const { icon: Icon, label, href } = slot
  return (
    <Link
      href={href}
      className={cn(
        'flex flex-1 flex-col items-center justify-center gap-1',
        'min-h-[44px] min-w-[44px]',
        'transition-colors duration-150',
        active
          ? 'text-primary'
          : 'text-muted-foreground hover:text-foreground',
      )}
      aria-current={active ? 'page' : undefined}
    >
      <Icon className="h-5 w-5 shrink-0" aria-hidden="true" />
      <span className="text-[10px] font-medium tracking-tight leading-none">
        {label}
      </span>
    </Link>
  )
}

