'use client'

import { useRef, useState } from 'react'
import { ArrowDown, Loader2 } from 'lucide-react'
import { cn } from '@/lib/utils'

interface PullToRefreshProps {
  onRefresh: () => Promise<void>
  children: React.ReactNode
  /** Pull threshold in px. Default: 80. */
  threshold?: number
  /** Disable on desktop — only activates on touch devices. Default: true. */
  disableOnDesktop?: boolean
  className?: string
}

function isTouchDevice(): boolean {
  return 'ontouchstart' in window || navigator.maxTouchPoints > 0
}

/**
 * Wrap a scrollable page section to enable pull-to-refresh.
 * Uses native PointerEvents — no external library needed.
 * Only activates when the container is scrolled to the top.
 *
 * Usage:
 *   <PullToRefresh onRefresh={async () => { router.refresh() }}>
 *     <DataTable ... />
 *   </PullToRefresh>
 */
export function PullToRefresh({
  onRefresh,
  children,
  threshold = 80,
  disableOnDesktop = true,
  className,
}: PullToRefreshProps) {
  const containerRef = useRef<HTMLDivElement>(null)
  const startYRef = useRef(0)
  // isDraggingRef is the source of truth for event handlers (no re-render cost).
  // isDragging state drives the CSS transition — must be state, not ref, in JSX.
  const isDraggingRef = useRef(false)
  const [isDragging, setIsDragging] = useState(false)
  const [pullDistance, setPullDistance] = useState(0)
  const [isRefreshing, setIsRefreshing] = useState(false)

  const pullProgress = Math.min(pullDistance / threshold, 1)

  const indicatorLabel =
    isRefreshing
      ? 'Refreshing\u2026'
      : pullProgress >= 1
        ? 'Release to refresh'
        : 'Pull to refresh'

  function onPointerDown(e: React.PointerEvent) {
    if (isRefreshing) return
    if (containerRef.current && containerRef.current.scrollTop > 0) return
    if (disableOnDesktop && !isTouchDevice()) return
    isDraggingRef.current = true
    setIsDragging(true)
    startYRef.current = e.clientY
    containerRef.current?.setPointerCapture(e.pointerId)
  }

  function onPointerMove(e: React.PointerEvent) {
    if (!isDraggingRef.current || isRefreshing) return
    const delta = e.clientY - startYRef.current
    if (delta <= 0) return
    // Rubber-band resistance factor 0.5; cap at 1.5× threshold
    setPullDistance(Math.min(delta * 0.5, threshold * 1.5))
  }

  function onPointerUp() {
    if (!isDraggingRef.current) return
    isDraggingRef.current = false
    setIsDragging(false)
    if (pullDistance >= threshold) {
      setIsRefreshing(true)
      setPullDistance(threshold) // hold at threshold while refreshing
      void Promise.resolve(onRefresh()).finally(() => {
        setIsRefreshing(false)
        setPullDistance(0)
      })
    } else {
      setPullDistance(0)
    }
  }

  return (
    <div
      ref={containerRef}
      className={cn('pull-to-refresh-container relative overflow-y-auto', className)}
      onPointerDown={onPointerDown}
      onPointerMove={onPointerMove}
      onPointerUp={onPointerUp}
      onPointerCancel={onPointerUp}
      style={{
        transform:
          isRefreshing || pullDistance > 0
            ? `translateY(${Math.min(pullDistance, threshold)}px)`
            : undefined,
        transition: !isDragging ? 'transform 200ms ease-out' : undefined,
      }}
    >
      {/* Indicator — visible when pulling or refreshing */}
      {(pullDistance > 0 || isRefreshing) && (
        <div
          aria-live="polite"
          aria-label={indicatorLabel}
          className={cn(
            'absolute left-0 right-0 top-0 flex items-center justify-center gap-2',
            'text-[12px] text-muted-foreground pointer-events-none select-none',
            'transition-opacity duration-200',
          )}
          style={{
            transform: `translateY(${indicatorLabel === 'Refreshing\u2026' ? -threshold : -pullDistance}px)`,
            opacity: pullProgress,
          }}
        >
          {isRefreshing ? (
            <Loader2 className="size-4 animate-spin" aria-hidden="true" />
          ) : (
            <ArrowDown
              className={cn(
                'size-4 transition-transform duration-200',
                pullProgress >= 1 && 'rotate-180',
              )}
              aria-hidden="true"
            />
          )}
          <span>{indicatorLabel}</span>
        </div>
      )}

      {children}
    </div>
  )
}

'use client'

import { useEffect, useRef } from 'react'
import { useRouter } from 'next/navigation'
import {
  CalendarDays,
  Clock,
  LayoutDashboard,
  Package,
  Plus,
  Receipt,
  Search,
  Settings,
  UserCircle,
  UserPlus,
  Users,
} from 'lucide-react'
import {
  Command,
  CommandDialog,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
  CommandSeparator,
  CommandShortcut,
} from '@/components/ui/command'
import { Sheet, SheetContent } from '@/components/ui/sheet'
import { useIsMobile } from '@/hooks/useIsMobile'

interface CommandPaletteProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  onCreateClient?: () => void
}

const G_CHORD_TIMEOUT_MS = 500

const NAV_ITEMS = [
  { label: 'Dashboard', href: '/dashboard', icon: LayoutDashboard, chord: 'D' },
  { label: 'Calendar', href: '/calendar', icon: CalendarDays, chord: 'C' },
  { label: 'Clients', href: '/clients', icon: Users, chord: 'L' },
  { label: 'Artists', href: '/artists', icon: UserCircle, chord: 'A' },
  { label: 'Settings', href: '/settings', icon: Settings, chord: 'S' },
  { label: 'Payroll', href: '/payroll', icon: Receipt, chord: 'P' },
  { label: 'Billing', href: '/settings/billing', icon: Receipt, chord: 'B' },
  { label: 'Inventory', href: '/inventory', icon: Package, chord: 'I' },
  { label: 'Waitlist', href: '/waitlist', icon: Clock, chord: 'W' },
  { label: 'Consent Forms', href: '/consent-forms', icon: Users, chord: 'N' },
]

// ─── CommandContent extracted at module level to avoid "component created during render" lint ───
interface CommandContentProps {
  isMobile: boolean
  onNavigate: (href: string) => void
  onClose: () => void
  onCreateClient?: () => void
}

function CommandContent({ isMobile, onNavigate, onClose, onCreateClient }: CommandContentProps) {
  return (
    <Command className="rounded-xl border-0">
      <CommandInput
        placeholder="Search or jump to..."
        className={isMobile ? 'h-12 text-base' : undefined}
      />
      <CommandList>
        <CommandEmpty>
          <span className="text-sm text-muted-foreground">No results found</span>
        </CommandEmpty>

        <CommandGroup heading="Quick Actions">
          <CommandItem onSelect={() => onNavigate('/appointments/new')}>
            <Plus className="mr-2 h-4 w-4" aria-hidden="true" />
            New Booking
            <CommandShortcut>N</CommandShortcut>
          </CommandItem>
          <CommandItem onSelect={() => onNavigate('/calendar?view=new')}>
            <CalendarDays className="mr-2 h-4 w-4" aria-hidden="true" />
            New Appointment
            <CommandShortcut>A</CommandShortcut>
          </CommandItem>
          <CommandItem
            onSelect={() => {
              onClose()
              onCreateClient?.()
            }}
          >
            <UserPlus className="mr-2 h-4 w-4" aria-hidden="true" />
            Create client
            <CommandShortcut>C</CommandShortcut>
          </CommandItem>
        </CommandGroup>

        <CommandSeparator />

        <CommandGroup heading="Navigate">
          {NAV_ITEMS.map((item) => (
            <CommandItem key={item.href} onSelect={() => onNavigate(item.href)}>
              <item.icon className="mr-2 h-4 w-4" aria-hidden="true" />
              {item.label}
              <CommandShortcut>
                <span className="flex items-center gap-0.5">
                  <kbd className="rounded bg-muted px-1 text-[10px]">G</kbd>
                  <kbd className="rounded bg-muted px-1 text-[10px]">{item.chord}</kbd>
                </span>
              </CommandShortcut>
            </CommandItem>
          ))}
        </CommandGroup>

        <CommandSeparator />

        <CommandGroup heading="Recent">
          <CommandItem onSelect={() => onNavigate('/appointments')}>
            <Search className="mr-2 h-4 w-4 text-muted-foreground" aria-hidden="true" />
            <span className="text-muted-foreground">Kai Johnson · Appointment</span>
          </CommandItem>
          <CommandItem onSelect={() => onNavigate('/clients')}>
            <Search className="mr-2 h-4 w-4 text-muted-foreground" aria-hidden="true" />
            <span className="text-muted-foreground">Sofia Chen · New client</span>
          </CommandItem>
        </CommandGroup>
      </CommandList>
    </Command>
  )
}

export function CommandPalette({ open, onOpenChange, onCreateClient }: CommandPaletteProps) {
  const router = useRouter()
  const isMobile = useIsMobile()
  const lastKeyRef = useRef<string>('')
  const lastKeyTimeRef = useRef<number>(0)

  function navigate(href: string) {
    onOpenChange(false)
    router.push(href)
  }

  // G+X chord handler — mounted globally from AppHeader, but also here for palette-open navigation
  useEffect(() => {
    if (!open) return

    function handleKeyDown(e: KeyboardEvent) {
      if (e.metaKey || e.ctrlKey || e.altKey) return
      const target = e.target as HTMLElement
      if (target.tagName === 'INPUT' || target.tagName === 'TEXTAREA') return

      const now = Date.now()
      const key = e.key.toLowerCase()

      if (
        lastKeyRef.current === 'g' &&
        now - lastKeyTimeRef.current < G_CHORD_TIMEOUT_MS
      ) {
        const match = NAV_ITEMS.find((n) => n.chord.toLowerCase() === key)
        if (match) {
          e.preventDefault()
          navigate(match.href)
          lastKeyRef.current = ''
          return
        }
      }

      lastKeyRef.current = key
      lastKeyTimeRef.current = now
    }

    window.addEventListener('keydown', handleKeyDown)
    return () => window.removeEventListener('keydown', handleKeyDown)
  }, [open]) // eslint-disable-line react-hooks/exhaustive-deps

  // B2: mobile → Sheet side="bottom"; desktop → CommandDialog
  if (isMobile) {
    return (
      <Sheet open={open} onOpenChange={onOpenChange}>
        <SheetContent
          side="bottom"
          className="h-[85vh] p-0 flex flex-col rounded-t-2xl safe-bottom"
          showCloseButton={false}
        >
          {/* Drag handle */}
          <div className="flex justify-center pt-3 pb-1 shrink-0" aria-hidden="true">
            <div className="h-1 w-10 rounded-full bg-border/60" />
          </div>
          <CommandContent
            isMobile={isMobile}
            onNavigate={navigate}
            onClose={() => onOpenChange(false)}
            onCreateClient={onCreateClient}
          />
        </SheetContent>
      </Sheet>
    )
  }

  return (
    <CommandDialog open={open} onOpenChange={onOpenChange}>
      <CommandContent
        isMobile={isMobile}
        onNavigate={navigate}
        onClose={() => onOpenChange(false)}
        onCreateClient={onCreateClient}
      />
    </CommandDialog>
  )
}

